def I(n,kind,loc,quote,statement,rec,reason,verdict='kept',check='agrees',extra=()):
    nums=[n,*extra]; locs=[]
    for c,s,a,b in loc:
        locs.append({'file':f'pro/{PK}_transcription.tex','cote':c,'scan':s,'start':a,'end':b})
    ident=f'SA13-{99+n}'
    items.append(dict(id=ident,sources=[f'{PK}#{j}' for j in nums],kind=kind,cote=sorted(set(x[0] for x in loc)),scans=list(dict.fromkeys(f'{x[0]}:{x[1]:03}' for x in loc)),lines=locs,his_words=quote,statement=statement,reconstruction=rec,check=check,check_reason=reason,title=notes[n-1]['heading']))
    for j in nums: verdicts.append(dict(entry_id=f'{PK}#{j}',item_id=ident,verdict=verdict if j==n else 'merged',reason=reason if j==n else f'Same object or documentary inventory as entry #{n}; combined after reading both entries and passages. '+reason))

