def write():
    OUT.joinpath('items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
    with OUT.joinpath('entries.tsv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=['entry_id','item_id','verdict','reason'],delimiter='\t');w.writeheader();w.writerows(sorted(verdicts,key=lambda x:int(x['entry_id'].split('#')[1])))
    print(f'Manually reviewed {len(verdicts)} entries in {len(items)} items.')

if __name__=='__main__':write()
